// Shape the callback body. Pass org_id/client_id through from the webhook,
// and roll every queried row into a {bot_template_id, name, value} list.
const trigger = $node["Webhook"].json.body || {};
const rows = $input.all();
const variables = rows.map((r) => ({
  bot_template_id: r.json.bot_template_id,
  name: r.json.variable_name,
  value: r.json.variable_value
}));
return [{ json: { org_id: trigger.org_id, client_id: trigger.client_id, variables } }];
